insert into public.course_modules (seed_key, title, description, order_number, metadata, course_id) values ($wdthseed$biology:mod08$wdthseed$, $wdthseed$Human Biology$wdthseed$, $wdthseed$How the human body feeds, pumps, breathes, senses and balances itself — digestion, circulation, respiration, nerves and homeostasis.$wdthseed$, 8, $wdthseed${"objectives":["Trace food through digestion to absorption","Explain the double circulation and gas exchange","Describe nervous control and homeostasis"],"duration_text":"2 weeks"}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, order_number = excluded.order_number, metadata = excluded.metadata, course_id = excluded.course_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod08:top01$wdthseed$, $wdthseed$Nutrition and Digestion$wdthseed$, $wdthseed$Balanced diet and the journey of food from mouth to bloodstream.$wdthseed$, NULL, 1, TRUE, TRUE, $wdthseed${"objectives":["Define balanced diet","Trace digestion with enzymes"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod08$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod08:top01:les01$wdthseed$, $wdthseed$Food and a Balanced Diet$wdthseed$, $wdthseed$Nutrient groups, deficiency diseases, and what 'balanced' actually means.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A labourer needs twice the energy of an office worker; a pregnant mother needs extra iron and folate. 'Balanced diet' is not one menu — it is matching intake to need.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top01:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Seven components$wdthseed$, $wdthseed$CARBOHYDRATES (yam, rice, cassava): cheap energy. PROTEINS (beans, soya, fish, eggs, milk): growth and repair — children and mothers need most. FATS/OILS (palm oil, groundnuts): concentrated energy, insulation, vitamin carriers. VITAMINS (fruits, vegetables): regulators in tiny doses — C (oranges, mango) prevents scurvy and aids iron uptake; D (sunlight, fish) builds bone with calcium; A (palm oil, liver, orange sweet potato) protects vision and immunity. MINERALS: iron (blood haemoglobin — deficiency causes ANAEMIA: fatigue, pale gums); calcium + phosphorus (bones/teeth — deficiency causes RICKETS in children); iodine (thyroid — deficiency causes GOITRE). FIBRE (vegetables, whole grains): prevents constipation and feeds gut flora. WATER: solvent, coolant (sweat), transport — 2+ litres daily in our climate. Deficiency diseases are diagnosable: kwashiorkor (protein), marasmus (total energy), night blindness (vitamin A), scurvy (vitamin C).$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top01:les01:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: diagnosing from symptoms$wdthseed$, $wdthseed$Question: A 3-year-old has swollen belly and legs, thin arms, reddish hair and slow healing. Diagnose and prescribe foods. Step 1 — Match symptoms: oedema (swelling) + muscle wasting + hair changes = KWASHIOKROR (protein deficiency), not mere hunger (marasmus wastes uniformly without oedema). Step 2 — Explain: without protein, blood albumin falls so fluid leaks into tissues; growth and immunity stall. Step 3 — Prescribe: beans, soya milk, groundnuts, eggs, dried fish — affordable local proteins — plus medical care (severe cases need hospital feeding). Prevention moral: exclusive breastfeeding then protein-rich weaning foods. Examination tip: kwashiorkor = protein lack (swelling); marasmus = energy lack (matchstick, no swelling).$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top01:les01:blk03$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Seven components: carbs, protein, fats, vitamins, minerals, fibre, water.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top01:les01:blk04$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Every nutrient has jobs and every shortage has symptoms. Read bodies like case notes — swelling, pallor, bleeding gums and bent bones each name their missing nutrient — then prescribe from local foods.$wdthseed$, NULL, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod08:top01:les02$wdthseed$, $wdthseed$Digestion from Mouth to Blood$wdthseed$, $wdthseed$Mechanical and chemical digestion, the enzyme line-up, and absorption in the ileum.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=1UvuBYUbFk0$wdthseed$, $wdthseed$A pounded-yam meal becomes blood glucose in hours. Follow it down 9 metres of gut — chewed, churned, dissolved and absorbed with industrial efficiency.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top01:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The journey$wdthseed$, $wdthseed$MOUTH: teeth CHEW (mechanical — bigger surface); salivary AMYLASE starts starch → maltose (alkaline pH). OESOPHAGUS: PERISTALSIS (muscular waves) pushes the bolus down — swallowing works upside-down. STOMACH: acid (pH ~2, kills germs) + PEPSIN (protein → peptides) + churning → chyme; mucus shields the wall (failure = ulcer). SMALL INTESTINE (duodenum + ileum): the main event — PANCREATIC juice brings AMYLASE (starch → maltose), TRYPSIN (protein → peptides), LIPASE (fats → fatty acids + glycerol); BILE from the liver (stored in gall bladder) EMULSIFIES fats and neutralises acid (no enzymes in bile); intestinal enzymes finish maltose → glucose, peptides → amino acids. ILEUM: millions of VILLI (+ microvilli) absorb glucose/amino acids into blood capillaries and fatty acids/glycerol into lacteals. LARGE INTESTINE: absorbs WATER and salts; gut bacteria make vitamin K; faeces (fibre, dead cells, bacteria) egested — EGESTION removes undigested waste, EXCRETION removes metabolic waste (never confuse them).$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top01:les02:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: tracing groundnuts$wdthseed$, $wdthseed$Question: Trace a groundnut's fat from mouth to bloodstream. Step 1 — Mouth/stomach: chewing and churning break pieces; NO fat digestion (no lipase yet). Step 2 — Duodenum: bile EMULSIFIES the fat into droplets (surface area soars); pancreatic LIPASE hydrolyses droplets → fatty acids + glycerol (alkaline pH). Step 3 — Ileum: products diffuse into villi — into LACTEALS (not blood capillaries) — then to lymph and blood. Step 4 — Note the checkpoints: emulsification is PHYSICAL (no enzymes), lipase is CHEMICAL, lacteals are the FAT route. Examination sentence: 'Bile emulsifies fats, increasing surface area for lipase' — write it exactly.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top01:les02:blk03$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: Digestive System$wdthseed$, $wdthseed$Watch 'Digestive System' by the Amoeba Sisters (official channel stream). Afterwards, list every gut region with its pH and enzymes from memory.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=1UvuBYUbFk0$wdthseed$, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top01:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Amylase: starch → maltose (mouth, pancreas). Pepsin/trypsin: protein → peptides → amino acids. Lipase: fats → fatty acids + glycerol. Bile: emulsifies, neutralises — NO enzymes.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top01:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Digestion is disassembly: mechanical breaking, enzymatic hydrolysis, then absorption through vast villi. Bile prepares, lipase dissolves, lacteals collect — and the large intestine reclaims the water.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
