insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod08:top02$wdthseed$, $wdthseed$Circulation and Respiration$wdthseed$, $wdthseed$The double circulation, blood, breathing and how cells release energy.$wdthseed$, NULL, 2, TRUE, TRUE, $wdthseed${"objectives":["Trace blood through the heart","Explain gas exchange and breathing"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod08$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod08:top02:les01$wdthseed$, $wdthseed$The Heart and Blood$wdthseed$, $wdthseed$Double circulation, vessels, blood cells and what goes wrong (hypertension, anaemia).$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Your heart beats 100,000 times a day, pushing 7,000 litres through 100,000 km of vessels. It is two pumps in one — and understanding it explains blood pressure, heart attacks and why exercise matters.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top02:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Double circulation$wdthseed$, $wdthseed$Mammals run TWO circuits. PULMONARY (lungs): right atrium → right ventricle → PULMONARY ARTERY (carries DEOXYGENATED blood — the great exception) → lungs (CO2 out, O2 in) → PULMONARY VEIN (OXYGENATED — the other exception) → left atrium. SYSTEMIC (body): left atrium → LEFT VENTRICLE (thickest wall — pumps body-wide at high pressure) → AORTA → body tissues (O2/glucose out, CO2/waste in) → VENA CAVA → right atrium. VALVES enforce one-way flow: bicuspid/mitral (left), tricuspid (right), and semilunar valves at artery exits (their snap shut makes the heartbeat's 'lub-dub'). Coronary arteries feed the heart muscle itself — their blockage causes heart attacks. VESSELS: arteries (thick muscle/elastic, small lumen, high pressure, pulse); veins (thin walls, wide lumen, VALVES, low pressure); capillaries (ONE cell thick, narrow — exchange only, white cells squeeze through).$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top02:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Blood and pressure$wdthseed$, $wdthseed$RED CELLS: biconcave discs, NO nucleus, packed with HAEMOGLOBIN — maximum oxygen loading; made in bone marrow, living 120 days (malaria and sickle cell destroy them). WHITE CELLS: larger, with nuclei — PHAGOCYTES engulf germs, LYMPHOCYTES make ANTIBODIES (vaccination trains them). PLATELETS: cell fragments triggering CLOTTING (fibrin mesh seals wounds; haemophilia breaks this). PLASMA: pale fluid carrying dissolved glucose, amino acids, hormones, urea, antibodies and heat. BLOOD PRESSURE: force on artery walls (~120/80 mmHg normal). HYPERTENSION (persistent high pressure — salt, obesity, stress, genetics) silently damages heart, brain (stroke), kidneys and eyes: the 'silent killer' — preventable by less salt, healthy weight, exercise and prescribed drugs taken faithfully.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top02:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: tracing an oxygen molecule$wdthseed$, $wdthseed$Question: Trace O2 from lung air to a leg muscle cell. Step 1 — Diffuses across alveolus + capillary walls into red cells (haemoglobin loads). Step 2 — Pulmonary vein → left atrium → left ventricle → aorta → leg artery → arteriole → capillary. Step 3 — Unloads (respiring muscle is low-O2, high-CO2 — haemoglobin releases there), diffuses into the muscle cell's mitochondria. Step 4 — Return trip: CO2 reverses the path to the right heart and lungs. Examination rule: name EVERY chamber and vessel in order — skipping the atria loses marks.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top02:les01:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Right heart = pulmonary (lungs); left heart = systemic (body). Pulmonary artery/vein break the oxygen rule.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top02:les01:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Two circuits, four chambers, one-way valves and three vessel types keep every cell supplied. Blood's four components transport, defend and seal — while blood pressure quietly reports the system's health.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod08:top02:les02$wdthseed$, $wdthseed$Breathing and Gas Exchange$wdthseed$, $wdthseed$The breathing mechanism, alveoli, and aerobic vs anaerobic respiration.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=eJ9Zjc-jdys$wdthseed$, $wdthseed$You breathe 20,000 times a day without thinking. Behind each breath: pressure physics, 300 million alveoli, and the respiration equation that powers Module 2's active transport.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top02:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Ventilation$wdthseed$, $wdthseed$INHALATION (active): external intercostal muscles contract → ribs move UP and OUT; diaphragm contracts and FLATTENS → chest volume INCREASES → pressure FALLS below outside → air rushes in. EXHALATION (passive at rest): muscles relax → ribs fall, diaphragm domes → volume DECREASES → pressure RISES → air pushed out (forced exhalation recruits internal intercostals and abdominal muscles). Air's path: nose/mouth (warmed, moistened, filtered by hairs/mucus) → trachea (C-shaped cartilage rings hold it open) → bronchi → bronchioles → ALVEOLI. Gas exchange at alveoli: O2 diffuses into blood, CO2 diffuses out — driven by concentration gradients maintained by breathing (ventilation) and heartbeat (perfusion). Adaptations: enormous surface (~100 m²), ONE-cell-thin walls, moist lining (gases dissolve), dense capillary nets.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top02:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Respiration equations$wdthseed$, $wdthseed$AEROBIC respiration (mitochondria, with oxygen): glucose + oxygen → carbon dioxide + water + LARGE energy (about 30 ATP per glucose). Word equation compulsory; symbol equation C6H12O6 + 6O2 → 6CO2 + 6H2O + energy earns bonus. ANAEROBIC respiration (no oxygen): in MUSCLE — glucose → lactic acid + SMALL energy (fast but weak; lactic acid causes cramp/fatigue, repaid later by deep breathing — oxygen debt); in YEAST/PLANTS — glucose → ethanol + carbon dioxide + small energy (FERMENTATION — brewing, baking, the Module 1 yeast bubbles). Smoking destroys this system: tar (carcinogen), carbon monoxide (binds haemoglobin 250x tighter than O2 — starving tissues), nicotine (addictive, narrows vessels) — causing bronchitis, emphysema (burst alveoli), lung cancer and heart disease.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top02:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the sprinter's debt$wdthseed$, $wdthseed$Question: After a 100 m sprint, an athlete breathes hard for minutes though the race is over. Explain. Step 1 — During the sprint, muscles needed ATP faster than blood could deliver O2 → ANAEROBIC respiration topped up supply, making LACTIC ACID. Step 2 — Afterward, the body must oxidise the lactate (in the liver) and repay the OXYGEN DEBT — hence sustained deep breathing and high heart rate. Step 3 — Contrast: a marathoner runs aerobically (steady O2 supply, no debt spike) — sprinting borrows energy anaerobically and repays with interest. Examination phrase: 'oxygen debt repaid by continued rapid breathing after exercise'.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top02:les02:blk04$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: Cellular Respiration (UPDATED)$wdthseed$, $wdthseed$Watch 'Cellular Respiration (UPDATED)' by the Amoeba Sisters (official channel stream). Write both respiration equations from memory afterwards, with the ATP comparison.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=eJ9Zjc-jdys$wdthseed$, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top02:les02:blk05$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Inhale: ribs up/out + diaphragm flat → volume up → pressure down → air in. Exhale reverses passively.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top02:les02:blk06$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Breathing ventilates, alveoli exchange, blood delivers, mitochondria burn. Aerobic respiration pays ~30 ATP per glucose; anaerobic loans ~2 and charges oxygen debt. Keep the system clean — it cannot be replaced.$wdthseed$, NULL, NULL, 6, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
