insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod08:top03$wdthseed$, $wdthseed$Control and Balance$wdthseed$, $wdthseed$Nerves, hormones and homeostasis — how the body senses change and stays constant.$wdthseed$, NULL, 3, TRUE, TRUE, $wdthseed${"objectives":["Describe reflex arcs","Explain temperature and glucose control"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod08$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod08:top03:les01$wdthseed$, $wdthseed$Nerves and Reflexes$wdthseed$, $wdthseed$Neurones, synapses and the reflex arcs that protect you before you think.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Your hand jerks from a hot pot before you feel pain. That reflex — sense, decide, act in milliseconds — is your nervous system at full speed.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top03:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Neurones and the arc$wdthseed$, $wdthseed$NEURONES carry electrical impulses. SENSORY neurones run receptor → CNS (brain/spinal cord); RELAY neurones (in the CNS) connect; MOTOR neurones run CNS → effector (muscle/gland). A motor neurone has dendrites (collect signals), a long AXON wrapped in MYELIN (fatty insulation speeding impulses ~100x), and synaptic terminals. SYNAPSES (gaps between neurones) pass signals CHEMICALLY: vesicles release neurotransmitters that diffuse across and trigger the next neurone (drugs, venoms and insecticides often target synapses). REFLEX ARC order: stimulus → receptor (skin pain endings) → sensory neurone → relay neurone (spinal cord) → motor neurone → effector (arm muscle contracts) — response WITHOUT waiting for the brain (the brain is informed after, for learning). Reflexes are fast, involuntary and protective: blinking, coughing, pupil changes, knee-jerk.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top03:les01:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the hot pot$wdthseed$, $wdthseed$Question: Order the events when a hand touches a hot pot. Step 1 — Receptor: pain endings in finger skin fire. Step 2 — Sensory neurone carries the impulse to the spinal cord. Step 3 — Relay neurone passes it (within the cord) to a motor neurone. Step 4 — Motor neurone fires the biceps; the hand withdraws. Step 5 — Meanwhile a branch ascends to the brain — you feel pain AFTER acting. Full marks need all five stations in order with the brain's late arrival noted. Contrast VOLUNTARY actions (picking up a cup): receptor → brain DECIDES → motor response — slower but flexible.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top03:les01:blk03$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Three neurones: sensory (in), relay (link), motor (out). Myelin speeds; synapses bridge chemically.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top03:les01:blk04$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Nerves wire fast, precise control: impulses race insulated axons, hop chemical synapses, and shortcut through reflex arcs when speed saves skin. Hormones handle the slow, body-wide messages.$wdthseed$, NULL, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod08:top03:les02$wdthseed$, $wdthseed$Homeostasis$wdthseed$, $wdthseed$Keeping temperature, water and glucose constant — the body's balancing act.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Desert noon or rainy night, your core stays near 37°C and your blood glucose near normal. Stray far and enzymes fail, brains fog, lives end — homeostasis is survival.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top03:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Temperature and water$wdthseed$, $wdthseed$HOMEOSTASIS = keeping internal conditions constant; NEGATIVE FEEDBACK = corrections opposing the change (like a thermostat). TOO HOT: hypothalamus detects warm blood → sweat glands release sweat (evaporation cools), skin arterioles VASODILATE (more blood near surface radiates heat), hair lies flat. TOO COLD: shivering (muscles respire → heat), VASOCONSTRICTION (blood kept deep — pale skin), hair stands (traps air — goosebumps), adrenaline boosts metabolism. WATER BALANCE: kidneys filter blood and reabsorb needed water (ADH hormone from the pituitary raises reabsorption when dehydrated — small, dark urine; excess water gives large, pale urine). Kidney failure is fatal without dialysis/transplant — drink water generously in our heat, and never ignore swelling or blood in urine.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top03:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top03:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Blood glucose and diabetes$wdthseed$, $wdthseed$The PANCREAS guards glucose. HIGH glucose (after eating): beta cells release INSULIN → liver/muscles convert glucose → GLYCOGEN (storage), cells absorb glucose → level falls. LOW glucose (exercise, hunger): alpha cells release GLUCAGON → liver converts glycogen → glucose → level rises. TYPE 1 DIABETES: beta cells destroyed (autoimmune) — no insulin; treated with INSULIN INJECTIONS for life (usually starts young). TYPE 2 DIABETES: cells resist insulin (linked to obesity, inactivity, age) — managed with diet, exercise, tablets, sometimes insulin. Uncontrolled diabetes damages eyes, kidneys, nerves and feet (amputations) — yet it is largely manageable: healthy weight, daily movement, less sugar, prescribed drugs, regular checks. Nigeria's diabetes burden is rising fast with urban diets — prevention starts on your plate.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top03:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top03:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the marathon runner$wdthseed$, $wdthseed$Question: During a marathon in heat, a runner sweats heavily, skin reddens, then later shivers at the finish. Explain both phases. Step 1 — Running phase: muscles generate heat → hypothalamus triggers SWEATING (evaporative cooling) + VASODILATION (red skin radiates heat) — negative feedback against rising core temperature. Step 2 — Finish phase: sweat-soaked and still, evaporation + breeze now OVERCOOL → shivering (respiratory heat) + vasoconstriction restore 37°C. Step 3 — Note the principle: opposite responses to opposite deviations, all automatic — homeostasis in one race. (Runners must also replace water AND salts — hyponatraemia kills.)$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top03:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top03:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Homeostasis = constancy via negative feedback (oppose the change).
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod08:top03:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Skin, kidneys and pancreas hold your inner world steady while the outer world swings. Negative feedback corrects every drift — and diabetes shows what happens when one loop breaks.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top03:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id) values ($wdthseed$biology:mod08:res1$wdthseed$, $wdthseed$OpenStax Biology 2e — full textbook (free PDF + web)$wdthseed$, $wdthseed$Module 8 reading: Chapters 33–41 selected (body organisation, circulation, respiration, nerves, hormones, nutrition). Download the free PDF from the publisher page.$wdthseed$, $wdthseed$https://openstax.org/details/books/biology-2e$wdthseed$, $wdthseed$OpenStax, Rice University$wdthseed$, $wdthseed$CC BY-NC-SA 4.0$wdthseed$, $wdthseed$Biology 2e by Mary Ann Clark, Matthew Douglas and Jung Choi (OpenStax, Rice University), licensed CC BY-NC-SA 4.0.$wdthseed$, $wdthseed$BOOK$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod08$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lesson_practicals (seed_key, title, objective, scenario, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, lesson_id, course_id, module_id) values ($wdthseed$biology:mod08:prac$wdthseed$, $wdthseed$Pulse, Breath and Recovery$wdthseed$, $wdthseed$Measure how exercise changes pulse and breathing rates and how fitness speeds recovery.$wdthseed$, $wdthseed$You are comparing your own recovery before and after two weeks of daily brisk walking (or comparing two volunteers).$wdthseed$, $wdthseed$1. REST: sit 5 minutes, then count your radial pulse for 30 seconds (×2 = bpm) and breaths for 30 seconds (×2). Record. 2. EXERCISE: step up/down a stair or march briskly for EXACTLY 2 minutes. 3. Immediately count pulse + breaths (0 min), then sit and repeat at 1, 2, 3, 4, 5 minutes. 4. Plot recovery curves (time vs bpm) on graph paper or described axes. 5. Repeat the whole test after 2 weeks of daily 20-minute brisk walks (or test a second person) and compare recovery times. 6. Conclude: why do rates rise (oxygen/glucose delivery, CO2/heat removal) and why does recovery quicken with fitness? SAFETY: stop for chest pain, dizziness or breathlessness; asthmatics keep inhalers handy and exercise gently; stay hydrated.$wdthseed$, $wdthseed$Watch/phone timer, stairs or stepping space, notebook.$wdthseed$, $wdthseed$Two data tables + recovery curves + physiological conclusion.$wdthseed$, $wdthseed$BEGINNER$wdthseed$::public.difficulty_level, 60, $wdthseed$TEXT$wdthseed$, $wdthseed$["Standardised exercise (same 2 minutes both tests)","Complete time-series tables with recovery times identified","Conclusion links rate rises to respiration demands and recovery to fitness"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top01:les01$wdthseed$), (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod08$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, objective = excluded.objective, scenario = excluded.scenario, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, lesson_id = excluded.lesson_id, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.assignments (seed_key, title, description, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, max_score, pass_score, course_id, module_id, lesson_id) values ($wdthseed$biology:mod08:asg$wdthseed$, $wdthseed$Diabetes Case File$wdthseed$, $wdthseed$Advise a newly diagnosed Type 2 diabetic uncle using homeostasis science.$wdthseed$, $wdthseed$Your 55-year-old uncle (okada rider, loves soft drinks and late eba) is diagnosed with Type 2 diabetes. Write him a 400–500 word letter: (1) explain in KIND, SIMPLE words what is happening to his blood glucose and insulin; (2) explain THREE dangers of ignoring it (eyes, kidneys/feet, heart) without terrifying him; (3) prescribe a realistic weekly plan — food swaps (keep eba but smaller + more vegetables?), daily movement fitting his job, drink rules, drug/faithful-checkup habits; (4) end with encouragement and ONE myth to ignore (e.g. 'bitter leaf cures diabetes' — it doesn't replace treatment). Tone: loving family member, not lecturer.$wdthseed$, $wdthseed$Medically accurate (no fake cures); culturally realistic for a Nigerian rider.$wdthseed$, $wdthseed$400–500 word advice letter covering mechanism, dangers, plan and myth-busting.$wdthseed$, $wdthseed$INTERMEDIATE$wdthseed$::public.difficulty_level, 100, $wdthseed$TEXT$wdthseed$, $wdthseed$["Correct insulin-resistance mechanism in simple words","Three real complications named","Realistic affordable plan + one myth corrected with the treatment message intact"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, 100, 50, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod08$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod08:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description 