insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod08:exam:quiz:q06$wdthseed$, $wdthseed$Which adaptations make alveoli efficient? (Select ALL that apply)$wdthseed$, $wdthseed$multiple_answer$wdthseed$, $wdthseed$["Huge total surface area","One-cell-thin walls","Dense capillary network","Thick muscular walls for pumping"]$wdthseed$::jsonb, $wdthseed$["Huge total surface area","One-cell-thin walls","Dense capillary network"]$wdthseed$::jsonb, $wdthseed$Area, thinness and blood supply maximise diffusion. Alveoli do not pump — breathing muscles move the air.$wdthseed$, 6, $wdthseed${"points":2,"topic_tag":"Gas exchange"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod08:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
