insert into public.course_modules (seed_key, title, description, order_number, metadata, course_id) values ($wdthseed$biology:mod09$wdthseed$, $wdthseed$Plant Biology$wdthseed$, $wdthseed$How plants feed themselves and reproduce: photosynthesis, transport, responses and the flowering-plant life cycle.$wdthseed$, 9, $wdthseed${"objectives":["Explain photosynthesis and its limiting factors","Describe water/mineral uptake and translocation","Trace pollination to germination in flowering plants"],"duration_text":"1 week"}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, order_number = excluded.order_number, metadata = excluded.metadata, course_id = excluded.course_id;
