insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod09:top01:les01$wdthseed$, $wdthseed$Leaves as Solar Factories$wdthseed$, $wdthseed$Chlorophyll, the photosynthesis equation, and how leaves maximise production.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=CMiPYHNNg28$wdthseed$, $wdthseed$A cassava leaf turns sunlight, air and water into the garri on your table. No factory on Earth matches it — and it runs silently, for free, while cleaning the air.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top01:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The equation$wdthseed$, $wdthseed$PHOTOSYNTHESIS: carbon dioxide + water → (light energy + chlorophyll) → glucose + oxygen. Symbol: 6CO2 + 6H2O → C6H12O6 + 6O2. It happens in CHLOROPLASTS: chlorophyll traps light, splitting water (photolysis — releasing the O2 we breathe) and fixing CO2 into glucose via the Calvin cycle. Glucose is then: RESPIRED for energy (plants respire day and night), CONVERTED to STARCH for storage (tubers, seeds), built into CELLULOSE for walls, combined with nitrates into AMINO ACIDS/PROTEINS, or stored as OILS (palm fruit, groundnut). Without photosynthesis there is no food chain, no oxygen atmosphere, no fossil fuel — every meal and every breath begins here.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top01:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Leaf adaptations$wdthseed$, $wdthseed$Leaves are optimised on five fronts. (1) BROAD and THIN: huge area catches light; short diffusion paths move gases fast. (2) CHLOROPHYLL packed in palisade mesophyll near the upper surface — most light meets most pigment. (3) STOMATA (pores, mostly underneath) + AIR SPACES let CO2 diffuse in and O2 out; guard cells open/close them to balance gas entry against water loss. (4) VEINS (xylem + phloem) deliver water and export sugars while stiffening the blade. (5) WAXY CUTICLE cuts evaporation while staying transparent. Desert plants modify the plan (spines, sunken stomata, CAM night-photosynthesis); water plants float stomata on top. Examination pattern: adaptation → feature → benefit ('stomata allow CO2 entry for photosynthesis').$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top01:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: why destarch?$wdthseed$, $wdthseed$Question: Before testing whether light is needed for photosynthesis, a plant is kept in darkness for 48 hours. Why? Step 1 — Recall: leaves STORE starch from earlier photosynthesis. Step 2 — Reason: old starch would give false positives everywhere — you could not tell NEW starch (made in your experiment) from OLD. Step 3 — Conclude: destarching empties the stores so any starch found later MUST have been made during the test — a control against prior conditions. Then the foil-star test (Module 8's final-exam question) proves light's necessity cleanly. Controls separate real causes from leftovers — the mark of valid experiments.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top01:les01:blk04$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: Photosynthesis (UPDATED)$wdthseed$, $wdthseed$Watch 'Photosynthesis (UPDATED)' by the Amoeba Sisters (official channel stream). Sketch and label a leaf cross-section from memory afterwards.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=CMiPYHNNg28$wdthseed$, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top01:les01:blk05$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$6CO2 + 6H2O →(light/chlorophyll) C6H12O6 + 6O2 in chloroplasts.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top01:les01:blk06$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Leaves are solar factories tuned by five adaptations, running the equation that feeds and oxygenates the planet. Glucose then branches into energy, stores, walls and proteins.$wdthseed$, NULL, NULL, 6, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
