insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id, topic_id, lesson_id) values ($wdthseed$biology:mod09:top01:les01:vid1:res$wdthseed$, $wdthseed$Photosynthesis (UPDATED)$wdthseed$, $wdthseed$Light reactions, Calvin cycle and leaf adaptations with desert-plant examples.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=CMiPYHNNg28$wdthseed$, $wdthseed$Amoeba Sisters$wdthseed$, $wdthseed$Standard YouTube License (official stream — no copy made)$wdthseed$, $wdthseed$© Amoeba Sisters — streamed from the official channel https://www.youtube.com/@AmoebaSisters$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod09$wdthseed$), (select id from public.course_topics where seed_key = $wdthseed$biology:mod09:top01$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id, topic_id = excluded.topic_id, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod09:top01:les02$wdthseed$, $wdthseed$Limiting Factors$wdthseed$, $wdthseed$Light, CO2 and temperature — which factor caps the rate, and how farmers exploit the answer.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A greenhouse farmer pumps in extra CO2 and harvests 30% more tomatoes. Same seeds, same soil — just one bottleneck removed. Limiting factors are profit.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top01:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Three graphs, one idea$wdthseed$, $wdthseed$A LIMITING FACTOR is the variable holding back the rate — raising it (alone) raises the rate until something else limits. LIGHT INTENSITY: rate climbs then plateaus (light no longer limits — CO2 or temperature does). CARBON DIOXIDE: same shape — enrichment boosts glasshouse crops until light/temperature cap out (note: open-field CO2 (~0.04%) almost always limits). TEMPERATURE: rises to an optimum (~25–35°C for most crops) then FALLS as enzymes denature — the asymmetric enzyme curve from Module 3. WATER rarely limits rate directly (except drought closing stomata). Measuring rate: oxygen bubbles from pondweed per minute, or CO2 uptake via sensors — with temperature, light and CO2 controlled except the one under test.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top01:les02:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: reading the plateau$wdthseed$, $wdthseed$Question: A farmer doubles lamp brightness over lettuce but yield does not rise. CO2 is at outdoor levels, temperature 20°C. Advise her. Step 1 — Diagnose: the light curve has PLATEAUED — light no longer limits; CO2 (or temperature) does. Step 2 — Prescribe: enrich CO2 (burners, fermentation tanks, or simply ventilate less) and/or warm toward the optimum — THEN extra light pays. Step 3 — Generalise: always find the CURRENT bottleneck before spending on inputs — fertiliser cannot fix a light shortage, water cannot fix nitrogen lack. This is Liebig's Law of the Minimum: growth is capped by the scarcest resource.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top01:les02:blk03$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Limiting factor = the variable currently capping the rate.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top01:les02:blk04$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Photosynthesis obeys bottlenecks: light, CO2 and temperature each cap the rate in turn. Read the curve, find the ceiling, lift it — the logic behind greenhouses and fertiliser advice alike.$wdthseed$, NULL, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod09:top02$wdthseed$, $wdthseed$Transport and Responses$wdthseed$, $wdthseed$Xylem and phloem, transpiration pull, and how plants sense light and gravity.$wdthseed$, NULL, 2, TRUE, TRUE, $wdthseed${"objectives":["Contrast xylem and phloem","Explain transpiration stream and tropisms"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod09$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod09:top02:les01$wdthseed$, $wdthseed$Moving Water and Food$wdthseed$, $wdthseed$Root uptake, the transpiration stream, and translocation of sugars.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A 30-metre iroko lifts hundreds of litres daily with no pump, no heart, no energy bill. It runs on evaporation — physics as plumbing.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top02:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Xylem: the water lift$wdthseed$, $wdthseed$ROOT HAIRS absorb soil water by OSMOSIS (Module 2) and minerals by ACTIVE TRANSPORT — their millions of extensions multiply area. Water crosses the root cortex to the XYLEM: dead, hollow, lignin-strengthened tubes running root → stem → leaf. The TRANSPIRATION STREAM pulls it up: (1) leaf cells lose water vapour through stomata (TRANSPIRATION — driven by heat, wind, dry air); (2) lost water is replaced from xylem; (3) water's COHESION (molecules gripping each other) + ADHESION (gripping walls) drags the whole column upward — one unbroken rope from roots to crown. Stomata regulate the trade: open for CO2 (photosynthesis) but losing water; closing in drought (abscisic acid triggers it) saves water but starves CO2. Wilting is lost turgor when loss beats uptake — recovered by watering, not by magic.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top02:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Phloem: the food network$wdthseed$, $wdthseed$PHLOEM (sieve tubes + companion cells — living, no nuclei in sieve elements) TRANSLOCATES sugars and amino acids from SOURCES (photosynthesising leaves, or storage organs in spring) to SINKS (roots, fruits, growing tips, storage tubers) — in ANY direction, unlike xylem's one-way climb. Flow is driven by pressure gradients (mass flow): sources load sugar (water follows by osmosis, raising pressure), sinks unload it (pressure falls) — sap streams from high to low pressure. Farmers exploit both systems: ring-barking (removing phloem) swells fruits above the cut; grafting joins one plant's shoot to another's roots via aligned cambia. Mineral needs: nitrates (proteins — deficiency yellows old leaves first), phosphates (roots/DNA/ATP), potassium (enzymes/stomata), magnesium (chlorophyll — deficiency yellows between veins).$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top02:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the bagged branch$wdthseed$, $wdthseed$Question: A clear plastic bag tied over a leafy branch collects water droplets inside by evening; a bag over a leafless branch stays dry. Explain. Step 1 — Source: droplets condensed from vapour the LEAVES transpired (stomata → air → bag → cool plastic → condense). Step 2 — Control: the leafless bag proves leaves (not bark or air) are the water source. Step 3 — Conclude: visible proof of transpiration — and your module practical repeats exactly this. Extension: morning vs noon bags show the rate follows heat/light — transpiration's drivers made visible.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top02:les01:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Root hairs (osmosis + active transport) → xylem (dead tubes) → transpiration pull (cohesion) → leaf.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top02:les01:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Xylem lifts by evaporation-pull through dead pipes; phloem delivers by pressure-flow through living ones. Stomata govern the water-carbon trade, and mineral shortages write their symptoms on leaves.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod09:top02:les02$wdthseed$, $wdthseed$How Plants Respond$wdthseed$, $wdthseed$Tropisms and hormones: auxin steering growth toward light and with gravity.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A seedling on your windowsill bends toward the light within days — with no eyes, muscles or brain. Hormones do the steering.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top02:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Auxin steering$wdthseed$, $wdthseed$TROPISM = directional growth response: PHOTOTROPISM (to light — shoots bend toward it) and GRAVITROPISM/GEOTROPISM (to gravity — roots grow down/positive, shoots grow up/negative). The hormone AUXIN (made in shoot tips) drives it: light makes auxin accumulate on the SHADED side; in SHOOTS, extra auxin SPEEDS cell elongation there — the shaded side outgrows the lit side, bending the shoot TOWARD light. In ROOTS the same extra auxin SLOWS elongation — the lower side grows less, bending the root DOWNWARD. One hormone, opposite effects by tissue — an examination favourite. Other hormones: GIBBERELLINS (stem elongation, seed germination — brewers sprout barley with them), CYTOKININS (cell division), ABSCISIC ACID (drought response — closes stomata, drops leaves), ETHENE (fruit ripening — traders ripen plantain with it).$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top02:les02:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the dark box$wdthseed$, $wdthseed$Question: Two identical seedlings: A in a box with a side hole (light one-sided), B in a fully dark box. After 5 days A bends toward the hole; B grows tall, pale and straight. Explain both. Step 1 — A: one-sided light → auxin gathers on the shaded side → faster elongation there → bends TOWARD light (positive phototropism). Step 2 — B: no light → auxin spreads evenly → straight growth; paleness = no chlorophyll made (etiolation) and tallness = the seedling 'searching' for light. Step 3 — Conclude: light DIRECTION steers (A), light ABSENCE starves (B) — tropism needs a gradient, which darkness cannot provide.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top02:les02:blk03$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Shoots: positive phototropism, negative gravitropism. Roots: positive gravitropism.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top02:les02:blk04$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Plants navigate with hormones: auxin gradients bend shoots to light and roots to earth. Farmers hijack the same signals to germinate, ripen and root crops on schedule.$wdthseed$, NULL, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod09:top03$wdthseed$, $wdthseed$Reproduction in Flowering Plants$wdthseed$, $wdthseed$Flower structure, pollination, fertilisation, seeds and germination.$wdthseed$, NULL, 3, TRUE, TRUE, $wdthseed${"objectives":["Label flower parts","Trace pollination to germination"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod09$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod09:top03:les01$wdthseed$, $wdthseed$Flowers and Pollination$wdthseed$, $wdthseed$Male and female parts, insect vs wind strategies, and fertilisation's double event.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A flower is advertising, engineering and nursery in one: colours and scents bribe couriers, structures load and receive pollen, and ovaries become the fruits we eat.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top03:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Structure and strategies$wdthseed$, $wdthseed$Flower parts: SEPALS (green, protect the bud) → PETALS (often bright/scented, attract insects) → STAMENS (male: anther makes POLLEN, filament holds it) → CARPEL(s) (female: stigma catches pollen, style connects, ovary holds OVULES with egg cells). INSECT-pollinated flowers: large bright petals, scent, nectar guides, sticky/spiky pollen, sticky stigma. WIND-pollinated (maize, grasses): tiny dull petals, NO scent/nectar, HUGE pollen quantities, light smooth grains, large FEATHERY stigmas dangling to catch drifting pollen, anthers dangling outside. POLLINATION = pollen landing on stigma (self: same flower/plant — fast, no variation; cross: different plant — variation, needs couriers). FERTILISATION follows: pollen germinates, a tube grows down the style, male nuclei enter the ovule — one fuses with the EGG (zygote → embryo), one fuses with endosperm nuclei (food store) — flowering plants' unique DOUBLE fertilisation.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top03:les01:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: maize tassels$wdthseed$, $wdthseed$Question: Maize grows male tassels at the very top and female silks (stigmas) lower down. Explain how this arrangement suits wind pollination AND reduces self-pollination. Step 1 — Wind logic: top tassels release clouds of light pollen that drift DOWN onto the feathery silks below — gravity assists the wind. Step 2 — Outbreeding logic: tassels shed pollen BEFORE most local silks emerge (or wind carries it to neighbouring plants first), favouring CROSS-pollination and variation. Step 3 — Conclude: position + timing turn wind from a gamble into a system — engineering without engineers. (Farmers bag tassels/silks to force controlled crosses in breeding programmes.)$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top03:les01:blk03$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Stamen = anther + filament (male). Carpel = stigma + style + ovary (female).
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top03:les01:blk04$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Flowers match their couriers: insect flowers advertise, wind flowers mass-produce. Pollen's landing is pollination; the tube's delivery is fertilisation — and the ovary's reward is fruit.$wdthseed$, NULL, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod09:top03:les02$wdthseed$, $wdthseed$Seeds and Germination$wdthseed$, $wdthseed$How fruits spread seeds, what seeds contain, and the three conditions for sprouting.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A mango seed cannot walk to a new clearing — so the fruit bribes you to carry it. Dispersal is the plant kingdom's travel industry.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top03:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Dispersal and the seed$wdthseed$, $wdthseed$After fertilisation, the OVARY wall becomes the FRUIT and OVULES become SEEDS (embryo + food store + protective TESTA). Dispersal methods: WIND — light, winged/plumed seeds (Tridax daisy fluff, mahogany wings); ANIMALS — tasty fruits eaten and dropped (mango, guava) or hooked burrs hitching fur/clothes (grasses); WATER — floating fibrous fruits (coconut husks ride oceans); EXPLOSIVE — pods flinging seeds (oil bean/pentaclethra, peas). Seeds contain the EMBRYO (plumule → shoot, radicle → root) plus food (endosperm or fat cotyledons — beans' fleshy halves). GERMINATION needs three conditions: WATER (activates enzymes, softens testa), OXYGEN (aerobic respiration for growth energy), and WARMTH (enzyme optimum) — light is NOT required (most seeds germinate underground; its absence even helps some).$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top03:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top03:les02:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: testing germination needs$wdthseed$, $wdthseed$Question: Design a test of whether water is needed for germination. Step 1 — Setup: two petri dishes (or plates with cotton wool), 10 bean seeds each, same warmth and air. DISH A: cotton wool DAMP. DISH B: cotton wool DRY (seeds present, everything else identical). Step 2 — Observe 5 days: A sprouts (radicles emerge), B stays hard. Step 3 — Conclude: water is necessary — the ONLY difference was water, so it caused the difference. Fair-test checklist: same seed type/number, same temperature, same air, only water varied. Repeat-logic gives the oxygen test (boiled-cooled water + oil layer excludes air) and warmth test (fridge vs room).$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top03:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top03:les02:blk03$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Fruit = ripened ovary; seed = embryo + store + testa. Dispersal: wind, animal, water, explosive.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod09:top03:les02:blk04$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Fruits are travel agents, seeds are packed lunches with babies inside, and germination waits only for water, air and warmth. Test each requirement by varying one factor — fair tests again.$wdthseed$, NULL, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top03:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id) values ($wdthseed$biology:mod09:res1$wdthseed$, $wdthseed$OpenStax Biology 2e — full textbook (free PDF + web)$wdthseed$, $wdthseed$Module 9 reading: Chapter 8 (Photosynthesis) and Chapters 30–32 (plant form, transport, reproduction). Download the free PDF from the publisher page.$wdthseed$, $wdthseed$https://openstax.org/details/books/biology-2e$wdthseed$, $wdthseed$OpenStax, Rice University$wdthseed$, $wdthseed$CC BY-NC-SA 4.0$wdthseed$, $wdthseed$Biology 2e by Mary Ann Clark, Matthew Douglas and Jung Choi (OpenStax, Rice University), licensed CC BY-NC-SA 4.0.$wdthseed$, $wdthseed$BOOK$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod09$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lesson_practicals (seed_key, title, objective, scenario, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, lesson_id, course_id, module_id) values ($wdthseed$biology:mod09:prac$wdthseed$, $wdthseed$Starch in Leaves + Transpiration Bags$wdthseed$, $wdthseed$Prove photosynthesis makes starch and make transpiration visible.$wdthseed$, $wdthseed$Two classic experiments, one afternoon — a destarched plant and a leafy branch.$wdthseed$, $wdthseed$PART A — STARCH TEST: 1. Destarch: keep a potted plant (or one branch covered) in darkness 48 hours. 2. Cover part of one leaf with foil (a shape), expose the plant to bright light 6+ hours. 3. Pluck the leaf: boil 2 min in water (soften, kill), then boil in ethanol in a HOT WATER BATH (no open flame — ethanol burns!) until pale, rinse, then add iodine. 4. Record: which areas turn blue-black? PART B — TRANSPIRATION: 5. Tie a clear dry bag over a leafy branch and another over a bare twig; leave 3 hours in sun. 6. Compare droplets. SAFETY: adult supervision for boiling; ethanol ONLY in a water bath away from flames; iodine stains; wash hands.$wdthseed$, $wdthseed$Potted plant, foil, ethanol, iodine, water bath/kettle, 2 clear bags, string.$wdthseed$, $wdthseed$Starch-test sketch with labelled areas + bag comparison + two conclusions (light→starch; leaves transpire).$wdthseed$, $wdthseed$INTERMEDIATE$wdthseed$::public.difficulty_level, 120, $wdthseed$TEXT$wdthseed$, $wdthseed$["Destarching + foil control correctly used","Ethanol safety step stated and followed","Both conclusions link evidence to photosynthesis/transpiration"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top01:les01$wdthseed$), (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod09$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, objective = excluded.objective, scenario = excluded.scenario, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, lesson_id = excluded.lesson_id, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.assignments (seed_key, title, description, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, max_score, pass_score, course_id, module_id, lesson_id) values ($wdthseed$biology:mod09:asg$wdthseed$, $wdthseed$Design a School Garden$wdthseed$, $wdthseed$Plan a productive 5 m × 5 m school garden applying photosynthesis, transport, soils and reproduction science.$wdthseed$, $wdthseed$Your school grants a 5 m × 5 m plot. Submit: (1) CROPS: choose 4 crops (one legume compulsory — explain its nitrogen gift) with spacing and reasons (light needs, root depth, season). (2) LAYOUT: describe/draw (in words) bed positions — tall crops north/south? paths? compost corner? water source? Justify with light/shade and labour logic. (3) CALENDAR: month-by-month for one term — sowing, weeding, watering, harvest. (4) SCIENCE NOTES: 200 words linking THREE module concepts to your choices (e.g. limiting factors → spacing; transpiration → mulching; pollination → border flowers for bees). (5) BUDGET: rough costs (seeds, tools, water) under a sensible total. 500–600 words total.$wdthseed$, $wdthseed$Must suit a real Nigerian school season and budget; fantasy tractors score zero.$wdthseed$, $wdthseed$Crop plan + layout + calendar + science notes + budget (500–600 words).$wdthseed$, $wdthseed$INTERMEDIATE$wdthseed$::public.difficulty_level, 120, $wdthseed$TEXT$wdthseed$, $wdthseed$["Legume included with correct nitrogen-fixation reasoning","Layout justified with light/water/labour logic","Three module concepts applied correctly to real choices"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, 100, 50, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod09$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod09:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, max_score = excluded.max_score, pass_score = excluded.pass_score, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id;
