insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod09:exam:quiz:q05$wdthseed$, $wdthseed$Old leaves yellowing first (chlorosis from the bottom up) most likely indicates deficiency of:$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["A mobile nutrient like nitrogen — the plant salvages it to young leaves","Water only","Sunlight only","Carbon dioxide"]$wdthseed$::jsonb, $wdthseed$"A mobile nutrient like nitrogen — the plant salvages it to young leaves"$wdthseed$::jsonb, $wdthseed$Mobile nutrients (N, P, K, Mg) are withdrawn from old leaves to growing tips — so old leaves yellow first. Immobile deficiencies (Fe, Ca) strike young leaves.$wdthseed$, 5, $wdthseed${"points":1,"topic_tag":"Nutrition"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod09:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
