insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod09:exam:quiz:q06$wdthseed$, $wdthseed$Which are leaf adaptations for photosynthesis? (Select ALL that apply)$wdthseed$, $wdthseed$multiple_answer$wdthseed$, $wdthseed$["Broad thin shape with large surface area","Chlorophyll-rich palisade layer near the top","Stomata and air spaces for gas diffusion","Thick opaque hairs blocking all light"]$wdthseed$::jsonb, $wdthseed$["Broad thin shape with large surface area","Chlorophyll-rich palisade layer near the top","Stomata and air spaces for gas diffusion"]$wdthseed$::jsonb, $wdthseed$Area, pigment placement and gas routes all boost photosynthesis. Blocking light would sabotage it (hairs reduce water loss, not boost photosynthesis).$wdthseed$, 6, $wdthseed${"points":2,"topic_tag":"Leaf"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod09:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
