insert into public.course_modules (seed_key, title, description, order_number, metadata, course_id) values ($wdthseed$biology:mod10$wdthseed$, $wdthseed$Practical Biology$wdthseed$, $wdthseed$Hands-on science: microscopy, slide preparation, biological drawing, safety and how to plan a valid investigation.$wdthseed$, 10, $wdthseed${"objectives":["Use a light microscope correctly and safely","Prepare slides and draw to biological standards","Plan, record and evaluate investigations"],"duration_text":"1 week"}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, order_number = excluded.order_number, metadata = excluded.metadata, course_id = excluded.course_id;
