insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod10:top01:les01$wdthseed$, $wdthseed$Using the Light Microscope$wdthseed$, $wdthseed$Parts, the focusing routine, magnification maths and microscope care.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=lo2aC_m2vyo$wdthseed$, $wdthseed$A microscope turns a drop of pond water into a safari. But one wrong twist of the coarse knob cracks the slide — technique first, safari second.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top01:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Parts and light path$wdthseed$, $wdthseed$Follow light's journey: MIRROR/LAMP (source) → CONDENSER + IRIS DIAPHRAGM (focus and dose the light) → STAGE + CLIPS (hold the slide) → SPECIMEN → OBJECTIVE LENSES on the NOSEPIECE (x4 scanning, x10 low, x40 high — short lens = low power) → BODY TUBE → EYEPIECE (usually x10) → your eye. FOCUSING knobs: COARSE (big moves — LOW power ONLY) and FINE (small moves — all powers, the ONLY knob on high power). Total magnification = eyepiece × objective (x10 × x40 = x400). Resolution (seeing two points as separate, ~0.2 µm for light microscopes) matters more than raw magnification — empty magnification enlarges blur. Electron microscopes resolve far finer but kill specimens and cost fortunes; light microscopes show LIVING cells cheaply.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top01:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The safe routine$wdthseed$, $wdthseed$Memorise this drill — practical examiners watch for it. (1) Carry with TWO hands (arm + base). (2) Start on the LOWEST objective (x4/x10) with the stage DOWN. (3) Place the slide, clip it, centre the specimen over the light hole. (4) Light on, diaphragm mid-open. (5) Looking from the SIDE, raise the stage nearly to the lens (avoids crashing). (6) Look through the eyepiece, LOWER the stage slowly with COARSE focus until sharp. (7) Centre the interesting area, switch to the next objective, sharpen with FINE focus ONLY. (8) Finish: lowest objective back, stage down, light off, cover on. Golden rules: coarse knob NEVER on high power; always start low and centre before switching up; never force anything — stiffness means something is wrong.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top01:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: field of view$wdthseed$, $wdthseed$Question: At x40 total magnification, the field of view is 4 mm across. An organism spans one-quarter of the field. How big is it? Step 1 — Field width = 4 mm. Step 2 — Organism = 1/4 × 4 mm = 1 mm = 1000 µm. Step 3 — State the method: estimate fraction of field × known field diameter. Extension: switching to x400 shrinks the field 10x (0.4 mm) — which is why centring on LOW power first is compulsory; high power shows a tiny window and you will lose the specimen otherwise.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top01:les01:blk04$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: How To Use a Compound Light Microscope$wdthseed$, $wdthseed$Watch 'How To Use a Compound Light Microscope: Biology Lab Tutorial' by Tami Guy / ScienceProfOnline (official channel stream). Copy the focusing routine into your notebook as a numbered drill.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=lo2aC_m2vyo$wdthseed$, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top01:les01:blk05$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: Focusing a Compound Microscope$wdthseed$, $wdthseed$Watch 'Focusing a compound microscope' by CUNY Kingsborough Biology (official account stream) — a short, precise demonstration of the low-to-high routine.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=rt5zbf0UEFI$wdthseed$, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
