insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id, topic_id, lesson_id) values ($wdthseed$biology:mod10:top01:les01:vid2:res$wdthseed$, $wdthseed$Focusing a compound microscope$wdthseed$, $wdthseed$Short college demonstration of focusing a compound microscope.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=rt5zbf0UEFI$wdthseed$, $wdthseed$CUNY Kingsborough Biology$wdthseed$, $wdthseed$Standard YouTube License (official stream — no copy made)$wdthseed$, $wdthseed$© Kingsborough Community College (CUNY) Biology — streamed from the official account https://www.youtube.com/@kingsboroughbio$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod10$wdthseed$), (select id from public.course_topics where seed_key = $wdthseed$biology:mod10:top01$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id, topic_id = excluded.topic_id, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod10:top01:les02$wdthseed$, $wdthseed$Slides and Biological Drawings$wdthseed$, $wdthseed$Preparing wet mounts and staining, plus drawing rules that earn practical marks.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A great biologist draws what they see — no imagination, no artistry, just honest lines. Practical papers mark drawings harder than essays.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top01:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Wet mounts$wdthseed$, $wdthseed$ONION EPIDERMIS (classic): peel the thin inner skin of an onion scale, spread FLAT on a drop of water (wrinkles ruin everything), add ONE drop of iodine stain (stains nuclei and starch brown-yellow — plant walls stay pale), lower the coverslip at 45° with a pin (hinge it down slowly — this pushes air out ahead; dropped flat, bubbles trap). BLOT excess liquid, then observe low → high. CHEEK CELLS: gentle toothpick scrape inside the cheek (your own mouth only, dispose safely), smear thin, stain with methylene blue, coverslip as above — nuclei pop blue against pale cytoplasm. RULES: thin specimens only (light must pass through); stain sparingly (over-staining blacks everything out); seal large mounts with petroleum jelly if observing long; dispose of biological waste safely and disinfect the bench.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top01:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The six drawing rules$wdthseed$, $wdthseed$Biological drawings are marked on: (1) SIZE — large (half a page), showing proportions; (2) LINES — sharp pencil, single continuous outlines, NO sketchy/feathered strokes, NO shading or colour (stipple dots only if texture is essential); (3) LABELS — straight ruled lines touching the structure exactly, label text at the end, never crossing lines; (4) TITLE + MAGNIFICATION — 'Onion epidermal cells (x100)' beneath, underlined; (5) HONESTY — draw ONLY what you see (no textbook additions — examiners compare with the real slide); (6) CELLS — adjacent cells share walls (single lines between, not double). Drawing magnification = drawing size ÷ real size — measure your drawn cell and divide by the known real size (or state the microscope magnification used).$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top01:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: marking a drawing$wdthseed$, $wdthseed$Question: A student's onion drawing is small (5 cm), shaded with cross-hatching, labelled with wavy freehand lines, titled 'cells'. Award feedback. Step 1 — Size: too small (should fill half a page) — proportions unreadable. Step 2 — Lines: shading FORBIDDEN in biological drawing; cross-hatching loses the line mark. Step 3 — Labels: must be ruled straight and touching — wavy freehand fails. Step 4 — Title: needs specimen + magnification ('Onion epidermis, x100'), underlined. Verdict: 0–1 of 4 presentation marks despite possibly correct biology — presentation IS biology in practical papers. Redo large, clean, ruled and titled.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top01:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Wet mount: flat specimen + drop of water + drop of stain + 45° coverslip + blot.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top01:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Good slides are thin, flat, lightly stained and bubble-free; good drawings are large, clean, ruled and honest. Both are motor skills — practise until the drill is automatic.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod10:top02$wdthseed$, $wdthseed$Classic Investigations$wdthseed$, $wdthseed$Osmosis, food tests and photosynthesis experiments — the practical canon.$wdthseed$, NULL, 2, TRUE, TRUE, $wdthseed${"objectives":["Run osmosis and food-test practicals","Present data properly"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod10$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod10:top02:les01$wdthseed$, $wdthseed$Osmosis and Diffusion Labs$wdthseed$, $wdthseed$Visking tubing, yam cylinders and what the numbers prove.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A sausage skin of Visking tubing filled with starch models your entire small intestine. Dialysis machines are just this idea, scaled up to save lives.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top02:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Model guts and potato cylinders$wdthseed$, $wdthseed$VISKING TUBING: a partially permeable membrane. Fill a tube with starch + glucose solution, seal it, place in distilled water: after 20 minutes, test the OUTER water — Benedict's goes positive (small glucose diffused OUT) while iodine stays brown (large starch stayed IN) — proving selective permeability by size. Test the INNER solution with iodine (still blue-black — starch trapped). YAM/POTATO CYLINDERS: identical cores in a RANGE of salt/sugar concentrations (0, 5, 10, 20%) for fixed time; measure MASS or LENGTH change → plot % change vs concentration → the curve CROSSES ZERO at the tissue's own concentration (isotonic point — read it off the graph). Fair-test essentials: identical cores (same borer, blot before weighing), same volumes/temperatures/times, repeats + means. Controls: distilled water (maximum gain) anchors the scale.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top02:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Tables and graphs that score$wdthseed$, $wdthseed$TABLES: ruled, with independent variable (concentration) in the LEFT column, dependent (mass change) next, units in HEADERS not cells ('Mass change / g'), repeats then a MEAN column, and a descriptive TITLE above. GRAPHS: independent variable on X, dependent on Y; labelled axes WITH units; even scales using 3/4+ of the paper; precise small plots (x or +); best-fit LINE (trends) or smooth CURVE (rates) — never dot-to-dot for continuous data; TITLE below. Calculate % change as (change ÷ original) × 100 — percentages allow fair comparison between different-sized cores. Read INTERCEPTS (zero-crossing = isotonic point) and GRADIENTS (steeper = faster osmosis) — graphs are arguments, not decorations.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top02:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the isotonic point$wdthseed$, $wdthseed$Question: Yam cores gained +8% (0% salt), +2% (5%), −5% (10%), −12% (20%). Estimate the yam's internal concentration. Step 1 — Plot % change (Y) vs salt % (X) with a best-fit curve. Step 2 — Find where the curve crosses ZERO change (no net osmosis = isotonic): between 5% (+2) and 10% (−5). Step 3 — Interpolate: zero sits about (2/7) of the way from 5 to 10 ≈ 6.4% salt equivalent. Step 4 — Conclude: yam cell sap ≈ 6–7% salt equivalent; below it cells gain water, above it they lose. This interpolation technique recurs in enzyme and photosynthesis graphs — master it once.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top02:les01:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Visking tubing proves size-selective permeability (glucose out, starch in).
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top02:les01:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Model guts and yam cores turn osmosis into numbers; tables organise them and graphs argue from them. The zero-crossing reads a tissue's inner concentration straight off the page.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod10:top02:les02$wdthseed$, $wdthseed$Food Tests and Leaf Tests Roundup$wdthseed$, $wdthseed$The complete practical canon: four food tests plus starch-in-leaf, in exam-ready form.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Practical examinations recycle the same dozen procedures yearly. This lesson compresses them into bulletproof sequences.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top02:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Food-test sequences$wdthseed$, $wdthseed$STARCH: sample + iodine → blue-black (no heat; brown-yellow = negative). REDUCING SUGAR: sample + Benedict's → HEAT in water bath 2–3 min → green/yellow/orange/brick-red by concentration (blue = negative). NON-REDUCING SUGAR: boil sample with dilute HCl → cool → neutralise with sodium hydrogencarbonate → Benedict's + heat → positive proves sucrose (the acid hydrolysed it). PROTEIN: sample + NaOH → few drops dilute CuSO4 → purple (blue = negative). FAT: shake with ethanol → pour into water → milky emulsion (or grease-spot on paper). SAFETY: goggles for heating/corrosives; water bath only (ethanol + flame = fire); tubes pointed away; tongs for hot tubes; rinse skin splashes immediately; controls (water) prove reagents are clean. Record OBSERVATION → INFERENCE separately for every tube.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top02:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Leaf-starch sequence$wdthseed$, $wdthseed$QUESTION: is light (or CO2, or chlorophyll) needed for photosynthesis? METHOD: (1) DESTARCH 48 h dark. (2) Set conditions: foil pattern (light test) / KOH-absorbed CO2 vs normal air (CO2 test) / variegated leaf (chlorophyll test — green vs white areas). (3) Bright light 6+ h. (4) Pluck leaf → boil in WATER (kill/soften) → boil in ETHANOL in water bath (remove chlorophyll — pale/white) → rinse → iodine. (5) Map blue-black areas against the treatment. PREDICTIONS: starch ONLY where light reached / CO2 present / chlorophyll present. CONTROLS: destarching (no old starch), plus untreated comparison leaf. CONCLUSION pattern: 'Starch formed only in [condition], therefore [factor] is necessary for photosynthesis.'$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top02:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the variegated leaf$wdthseed$, $wdthseed$Question: A variegated (green-and-white) leaf is destarched, lit 6 hours, then tested. Iodine turns ONLY green areas blue-black. Conclude. Step 1 — Compare: green areas (chlorophyll PRESENT) made starch; white areas (NO chlorophyll) made none — light, water and CO2 identical for both. Step 2 — Isolate the variable: the ONLY difference is chlorophyll. Step 3 — Conclude: chlorophyll is necessary for photosynthesis. Note the elegance: one leaf carries its own control (white areas) — internal controls beat separate setups. Examination phrase: 'the white areas act as a control, showing starch forms only where chlorophyll is present.'$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top02:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Five food sequences with colours: iodine, Benedict's, acid-then-Benedict's, biuret, emulsion.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top02:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Food tests identify molecules by colour; leaf tests identify necessities by mapping starch. Sequence, safety, controls, observation-then-inference — the practical canon in four habits.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod10:top03$wdthseed$, $wdthseed$Safety and Method$wdthseed$, $wdthseed$Laboratory safety, apparatus skills and designing valid investigations.$wdthseed$, NULL, 3, TRUE, TRUE, $wdthseed${"objectives":["State lab safety rules","Design fair, valid experiments"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod10$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod10:top03:les01$wdthseed$, $wdthseed$Staying Safe in the Lab$wdthseed$, $wdthseed$The rules that prevent the accidents — and what to do when they happen anyway.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=MEIXRLcC6RA$wdthseed$, $wdthseed$Acids blind, ethanol ignites, broken glass infects. Every rule below was written in someone's injury — learn them before you touch a bench.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top03:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Rules and responses$wdthseed$, $wdthseed$TEN RULES: (1) Goggles for heating, acids, alkalis, stains. (2) Tie hair, tuck ties/scarves, closed shoes, lab coat fastened. (3) NEVER taste, eat, drink or sniff directly (waft vapours). (4) Point heated tubes AWAY from people; use tongs and water baths. (5) Know exits, extinguisher, eyewash/shower, first-aid box, teacher's emergency stop. (6) Report ALL spills/breakages immediately — never hide them. (7) Dispose biologically/chemically as instructed (sharps bins, waste bottles — never sinks for chemicals). (8) Wash hands before leaving. (9) No running, no bags in aisles, stools tucked. (10) Follow the METHOD — improvisation causes accidents. EMERGENCIES: acid/alkali on skin → flood with water 10+ min, tell teacher; in eyes → eyewash immediately, keep flushing; burns → cool under running water 10+ min, no creams; cuts → pressure, raise, first aid; fire → alert, smother small flames (damp cloth/sand), evacuate for large ones; fainting → fresh air, sit/lie down.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top03:les01:blk02$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: General Lab Safety$wdthseed$, $wdthseed$Watch 'General Lab Safety' by the Amoeba Sisters (official channel stream). Write your personal top-5 rules card afterwards and keep it in your notebook.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=MEIXRLcC6RA$wdthseed$, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top03:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the spill$wdthseed$, $wdthseed$Question: A student knocks over dilute sodium hydroxide, splashing the bench and a sleeve. List the correct response order. Step 1 — Alert the teacher immediately (never silent). Step 2 — Remove the soaked sleeve carefully (avoid spreading to skin). Step 3 — Flood any skin contact with water for 10+ minutes. Step 4 — Let the teacher neutralise/clean the bench (students do not mop corrosives alone). Step 5 — Record the incident as required. Wrong answers examiners punish: wiping with bare hands, running to the toilet alone, or hiding it from fear. Safety culture rewards reporting — silence injures the next person.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top03:les01:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Goggles, tied hair, no tasting, tubes away, know exits and eyewash.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top03:les01:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Safety is choreography: dress right, handle right, know the exits, report everything. The best accident is the one your habits prevented.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
