insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id, topic_id, lesson_id) values ($wdthseed$biology:mod10:top03:les01:vid1:res$wdthseed$, $wdthseed$General Lab Safety$wdthseed$, $wdthseed$Core laboratory safety rules with memorable scenarios.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=MEIXRLcC6RA$wdthseed$, $wdthseed$Amoeba Sisters$wdthseed$, $wdthseed$Standard YouTube License (official stream — no copy made)$wdthseed$, $wdthseed$© Amoeba Sisters — streamed from the official channel https://www.youtube.com/@AmoebaSisters$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod10$wdthseed$), (select id from public.course_topics where seed_key = $wdthseed$biology:mod10:top03$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id, topic_id = excluded.topic_id, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod10:top03:les02$wdthseed$, $wdthseed$Designing Valid Investigations$wdthseed$, $wdthseed$Variables, fair tests, repeats, and judging validity like an examiner.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Anyone can do an experiment; scientists design ones whose answers can be TRUSTED. Validity is designed in — it cannot be added afterwards.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top03:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The design toolkit$wdthseed$, $wdthseed$VARIABLES: INDEPENDENT (what YOU change — e.g. light distance); DEPENDENT (what you MEASURE — bubbles per minute); CONTROL (what you HOLD CONSTANT — temperature, CO2, pondweed amount). FAIR TEST = one independent variable, all controls fixed. REPEATS (3+) + MEANS smooth random wobble; RANGES (5+ values of IV) reveal trends; CONTROLS (no-treatment setups) prove the IV caused the effect. VALIDITY (does it test the claim?) vs RELIABILITY (do repeats agree?): a valid method with tight repeats is trustworthy; valid-but-scattered needs more repeats; invalid-but-precise is precisely wrong. APPARATUS precision matters: measuring cylinders (±1 ml) beat beakers; thermometers beat 'warm to touch'; counting 60 seconds beats 10. SAMPLE SIZE: 30+ people for surveys, 10+ seeds per dish — small samples let chance dominate.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top03:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top03:les02:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: critiquing a method$wdthseed$, $wdthseed$Question: 'A student puts one seed in a warm cup and one in a cold cup, waters only the warm one, and concludes warmth aids germination.' Evaluate (4 marks). Step 1 — Praise (1): two conditions compared — the basic idea is right. Step 2 — Flaw 1: TWO variables changed (warmth AND water) — not a fair test; watering only the warm cup confounds the result. Step 3 — Flaw 2: n=1 per condition — no repeats, chance dominates (that seed might be dead). Step 4 — Improve: 10+ seeds per dish, water BOTH equally, vary ONLY temperature, repeat whole run. Evaluation formula: one strength + two flaws + two fixes = full evaluation marks on any method question.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top03:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top03:les02:blk03$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$IV = changed; DV = measured; controls = fixed. One IV per fair test.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod10:top03:les02:blk04$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Trustworthy experiments are built from variables controlled, repeats averaged, ranges explored and controls compared. Design validity in, then evaluate honestly — including your own work.$wdthseed$, NULL, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top03:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id) values ($wdthseed$biology:mod10:res1$wdthseed$, $wdthseed$OpenStax Biology 2e — full textbook (free PDF + web)$wdthseed$, $wdthseed$Module 10 reading: Chapter 1 (scientific method) and Chapter 4 (studying cells, microscopy). Download the free PDF from the publisher page.$wdthseed$, $wdthseed$https://openstax.org/details/books/biology-2e$wdthseed$, $wdthseed$OpenStax, Rice University$wdthseed$, $wdthseed$CC BY-NC-SA 4.0$wdthseed$, $wdthseed$Biology 2e by Mary Ann Clark, Matthew Douglas and Jung Choi (OpenStax, Rice University), licensed CC BY-NC-SA 4.0.$wdthseed$, $wdthseed$BOOK$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod10$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lesson_practicals (seed_key, title, objective, scenario, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, lesson_id, course_id, module_id) values ($wdthseed$biology:mod10:prac$wdthseed$, $wdthseed$Onion Cells Under the Microscope$wdthseed$, $wdthseed$Prepare a stained onion wet mount, observe at two magnifications, and produce an exam-standard drawing.$wdthseed$, $wdthseed$Your drawing will be marked exactly like a practical paper: presentation carries half the marks.$wdthseed$, $wdthseed$1. Peel inner onion epidermis, spread flat on a water drop (no wrinkles). 2. Add ONE drop of iodine, hinge the coverslip down at 45° with a pin, blot excess. 3. Focus low power (x40–x100 total): find flat cells, centre them. 4. Switch to high power (x400): fine focus ONLY; observe walls, cytoplasm, nuclei, vacuoles. 5. Draw HALF A PAGE: single pencil outlines, shared walls, no shading; label wall, nucleus, cytoplasm, vacuole with ruled touching lines; title + magnification underlined below. 6. Measure one drawn cell (mm), compute drawing magnification vs an assumed 0.4 mm real width. NO-MICROSCOPE ALTERNATIVE: use the two module videos + an online onion-cell image (describe source) to produce the same drawing to the same rules, noting it as a dry practical. SAFETY: iodine stains; pins sharp — point away; glass slides disposed in sharps, never bins.$wdthseed$, $wdthseed$Onion, slides/coverslips, iodine, microscope (or videos + image for dry option), sharp pencil, ruler.$wdthseed$, $wdthseed$Exam-standard half-page drawing with 4+ labels, title, magnification + calculation.$wdthseed$, $wdthseed$INTERMEDIATE$wdthseed$::public.difficulty_level, 90, $wdthseed$TEXT$wdthseed$, $wdthseed$["Slide technique described correctly (flat, stained, 45° coverslip)","Drawing obeys all six rules (size, lines, labels, title, honesty)","Magnification calculation shown with units"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top01:les01$wdthseed$), (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod10$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, objective = excluded.objective, scenario = excluded.scenario, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, lesson_id = excluded.lesson_id, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.assignments (seed_key, title, description, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, max_score, pass_score, course_id, module_id, lesson_id) values ($wdthseed$biology:mod10:asg$wdthseed$, $wdthseed$My Investigation — Plan and Report$wdthseed$, $wdthseed$Design and run your own fair-test investigation on germination, osmosis or photosynthesis, then report it fully.$wdthseed$, $wdthseed$Choose ONE question: (a) Does light colour affect seedling growth? (b) Does salt concentration affect yam mass? (c) Does leaf size affect transpiration (bag test)? Then submit: 1. HYPOTHESIS (one sentence, testable). 2. VARIABLES: IV, DV, and 4+ controls with HOW each is fixed. 3. METHOD: numbered steps another student could follow (apparatus + quantities). 4. RISK ASSESSMENT: 2 hazards + precautions. 5. RESULTS: table with repeats + means (real data you collected). 6. CONCLUSION linking results to the biology + 2 evaluation points (one strength, one improvement). 400–500 words plus tables.$wdthseed$, $wdthseed$Real data collected by you; invented results score zero for the whole assignment.$wdthseed$, $wdthseed$Full investigation report: hypothesis → variables → method → risks → results → conclusion + evaluation.$wdthseed$, $wdthseed$INTERMEDIATE$wdthseed$::public.difficulty_level, 150, $wdthseed$TEXT$wdthseed$, $wdthseed$["Single IV with 4+ controlled variables and real repeats","Method reproducible with quantities; risks sensible","Conclusion matches data with correct biology + honest evaluation"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, 100, 50, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod10$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod10:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, max_score = excluded.max_score, pass_score = excluded.pass_score, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id;
