insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod11:top01:les01$wdthseed$, $wdthseed$Cells to Genetics Express$wdthseed$, $wdthseed$One-pass review: life, cells, molecules, division and inheritance.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=jLmoJPxihjA$wdthseed$, $wdthseed$Five modules, one lesson: the facts that earn half the marks in any biology paper. Retrieve each from memory BEFORE reading on.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top01:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The non-negotiables (Modules 1–5)$wdthseed$, $wdthseed$MODULE 1: MRS GREN (all seven for life); cell = smallest living unit; five kingdoms by cell type/number/nutrition. MODULE 2: plant trio (wall, chloroplasts, big vacuole); prokaryote = no nucleus; diffusion (down gradient), osmosis (water + membrane), active transport (ATP, uphill); I = M × A. MODULE 3: starch/glycogen/cellulose roles; condensation out, hydrolysis in; enzyme curves (temperature cliff, pH optimum, substrate plateau); food colours — iodine blue-black (starch), Benedict's brick-red (sugar), biuret purple (protein), emulsion milky (fat). MODULE 4: PMAT + cytokinesis → 2 identical diploid; meiosis → 4 unique haploid; homologues part in anaphase I; variation = crossing over + assortment + random fertilisation. MODULE 5: five-step crosses; 3:1 and 1:2:1; ABO genotypes; X-linked males show single copies; normal parents + affected child = recessive. If any line above feels fuzzy, re-open that module NOW — Module 12 assumes mastery.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top01:les01:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the chain question$wdthseed$, $wdthseed$Question: 'Using cells, enzymes and genes, explain why a child with cystic fibrosis struggles to digest food.' (Chain across modules!) Step 1 — GENES (M5): the child is homozygous recessive for a faulty CFTR-channel allele. Step 2 — CELLS (M2): faulty channels trap chloride in cells; mucus dehydrates and thickens. Step 3 — ENZYMES (M3): thick mucus blocks pancreatic ducts, so lipase/trypsin never reach the gut — fats and proteins pass undigested. Step 4 — Conclude: one allele → broken transport → blocked enzymes → malnutrition. Examiners LOVE cross-module chains — practise building them: gene → protein → cell → system → symptom.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top01:les01:blk03$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: Mega Genetics Review (again, actively)$wdthseed$, $wdthseed$Rewatch 'Mega Genetics Review' by the Amoeba Sisters (official channel stream) — this time PAUSE before every solution and solve on paper. Active rewatching beats passive rereading.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=jLmoJPxihjA$wdthseed$, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
