insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top01:les01:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Modules 1–5 compress to: life's seven signs, cells' structures and traffic, molecules' colours and curves, divisions' precision and shuffling, and inheritance's ratios. Own them cold.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
