insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod11:top01:les02$wdthseed$, $wdthseed$Ecology to Practicals Express$wdthseed$, $wdthseed$One-pass review: evolution, ecology, humans, plants and practical skills.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$The second half of the course, same deal: retrieve first, read second. Ten modules down — finish the sweep.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top01:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The non-negotiables (Modules 6–10)$wdthseed$, $wdthseed$MODULE 6: selection = variation + competition + survival + inheritance; populations evolve; homologous (same build) vs analogous (same job); speciation = isolation → divergence → sterility. MODULE 7: arrows = energy flow; 10% transfers (respiration first); carbon in by photosynthesis, out by respiration/decay/combustion; nitrogen via Rhizobium → Nitrosomonas/Nitrobacter → plants → decay → denitrifiers; eutrophication chain; relationships scored +/−. MODULE 8: gut order + enzymes (amylase/pepsin/trypsin/lipase, bile emulsifies); heart trace (right=pulmonary, left=systemic, left ventricle thickest); breathe in = ribs up, diaphragm flat; aerobic ~30 ATP vs anaerobic ~2 + debt; insulin down/glucagon up; reflex arc five stations. MODULE 9: photosynthesis equation + five leaf adaptations + limiting factors; xylem up (transpiration pull), phloem any direction; germination = water + oxygen + warmth (no light). MODULE 10: microscope drill (low→high, fine-only); drawing rules (large, pencil, no shade, ruled labels); safety (goggles, water baths, report all); design (one IV, repeats, controls).$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top01:les02:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the synoptic chain$wdthseed$, $wdthseed$Question: 'Explain how deforestation can raise global temperatures AND reduce rainfall.' Step 1 — CARBON (M7): fewer trees = less CO2 absorbed + burning releases stored carbon → stronger greenhouse effect → warming. Step 2 — WATER (M9): fewer leaves = less TRANSPIRATION → less atmospheric moisture → fewer clouds → less rain downwind (the flying-rivers effect). Step 3 — FEEDBACK: drought kills more trees → cycle worsens. One question, three modules (ecology, plants, cycles) — synoptic answers name each link explicitly. Practise spotting which modules a question raids.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top01:les02:blk03$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Second-half spine: selection steps, cycles, traces, equations, drills.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top01:les02:blk04$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Modules 6–10 compress to mechanisms you can recite: selection, cycles, traces, equations and drills. Link them synoptically and no question can ambush you.$wdthseed$, NULL, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod11:top02$wdthseed$, $wdthseed$Exam Technique$wdthseed$, $wdthseed$Command words, marking logic, data questions and timing under pressure.$wdthseed$, NULL, 2, TRUE, TRUE, $wdthseed${"objectives":["Decode command words","Attack data questions systematically"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod11$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod11:top02:les01$wdthseed$, $wdthseed$Command Words and Marking$wdthseed$, $wdthseed$What STATE, DESCRIBE, EXPLAIN, EVALUATE and SUGGEST actually demand.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Students lose 20% of marks knowing the biology but missing the COMMAND. Technique is free marks — collect them.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top02:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The six commands$wdthseed$, $wdthseed$STATE/GIVE/NAME (1 mark each): bare facts, no explanation — 'Name the bond joining amino acids' → 'peptide bond.' Full stop. DESCRIBE: say WHAT happens (patterns, sequences) — no reasons. 'Describe the temperature curve' → 'rises to 37°C then falls steeply.' EXPLAIN: say WHY — mechanisms required. 'Explain the fall' → 'heat denatures the enzyme; the active site loses shape.' COMPARE: similarities AND differences, paired point-by-point (use 'both... whereas...' — one-sided answers halve marks). EVALUATE/DISCUSS: strengths + weaknesses + judgement with evidence. SUGGEST: apply knowledge to NEW situations — reason from first principles aloud; there is no memorised answer. MARK MATHS: 3 marks = 3 distinct points (number them); 'explain' chains need because-links; never contradict yourself (examiners mark wrong science even beside right science).$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top02:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Five classic mark-losers$wdthseed$, $wdthseed$(1) VAGUE AGENTS — 'it goes up the plant' (WHAT goes? water? sugar? name it). (2) MISSING COMPARISONS — describing one side of a compare question. (3) UNITS ABSENT — numbers without mm/°C/min bleed marks. (4) CONTRADICTIONS — 'diffusion needs no energy because ATP drives it' scores ZERO for the point. (5) ANSWERING ANOTHER QUESTION — restating the question's data instead of explaining it. Bonus time rule: minutes ≈ marks × 1.2 — a 5-mark question gets ~6 minutes, then MOVE ON; unfinished easy marks beat perfected hard ones. Always attempt everything: blank = zero, attempt ≥ zero.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
